import {test,expect,type Page} from '@playwright/test'
import {build} from 'esbuild'
import {readFile} from 'node:fs/promises'
test.describe.configure({retries:0,timeout:25000})
const origin='http://127.0.0.1:4266',prefix='/__tournaments/'
let javascript='',stylesheet=''
test.beforeAll(async()=>{const bundled=await build({entryPoints:['tests/fixtures/mobile-tournaments.ts'],bundle:true,platform:'browser',format:'esm',outfile:'tournaments.js',write:false,jsx:'automatic',loader:{'.module.css':'local-css'}});javascript=bundled.outputFiles.find(f=>f.path.endsWith('.js'))!.text;stylesheet=(await Promise.all(['style.css','website-ui.css','app.css','website-parity.css','app-atmosphere.css','premium-surfaces.css'].map(f=>readFile('mobile/bundled/'+f,'utf8')))).join('\n')})
test.beforeEach(async({page})=>{await page.route('**/*',async route=>{const u=new URL(route.request().url());if(u.origin!==origin||!u.pathname.startsWith(prefix))return route.abort();if(u.pathname.endsWith('app.js'))return route.fulfill({contentType:'text/javascript',body:javascript});if(u.pathname.endsWith('style.css'))return route.fulfill({contentType:'text/css',body:stylesheet});if(u.pathname!==prefix)return route.fulfill({status:404,body:''});return route.fulfill({contentType:'text/html',body:'<!doctype html><html lang="en"><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="./style.css"></head><body data-screen="lab"><header class="app-header">TenAceIQ</header><main id="app"></main><script type="module" src="./app.js"></script></body></html>'})})})
async function open(page:Page,mode=''){await page.goto(origin+prefix+'?view='+mode);await page.getByRole('button',{name:'Your competitions',exact:true}).click();await page.getByRole('button',{name:'Browse tournaments →',exact:true}).click();const d=page.getByRole('dialog',{name:'Tournaments',exact:true});await expect(d.getByRole('heading',{name:'Tournaments',exact:true})).toBeVisible();return d}
async function change(page:Page,v:Record<string,unknown>){await page.evaluate(v=>Object.assign((window as unknown as {tournamentFixture:{state:Record<string,unknown>}}).tournamentFixture.state,v),v)}
async function division(page:Page,mode=''){const d=await open(page,mode);await d.getByRole('button',{name:/^Open tournament/}).click();await d.getByRole('button',{name:/^Open division/}).click();await expect(d.getByRole('button',{name:'Draw',exact:true})).toBeVisible();return d}
async function bounded(page:Page){expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);expect(await page.getByRole('dialog',{name:'Tournaments',exact:true}).evaluate(e=>e.scrollWidth<=e.clientWidth)).toBe(true)}
test('tournament overview jumps to the upcoming court in the selected division',async({page},info)=>{
 await page.setViewportSize({width:320,height:844})
 await page.clock.setFixedTime(new Date('2026-11-08T15:00:00Z'))
 const dialog=await division(page)
 await page.addStyleTag({content:':root{font-size:22px!important}'})
 const jump=dialog.getByRole('button',{name:/^View in schedule for Alex Ace vs Jordan Serve/})
 await expect(jump).toHaveCount(1)
 await expect(jump.locator('..')).toContainText('Court 1')
 await expect(dialog.getByRole('button',{name:/^View in schedule for Alex Ace vs Casey Court/})).toHaveCount(0)
 const schedule=dialog.getByRole('button',{name:'Schedule',exact:true})
 const match=dialog.locator('[data-competition-schedule-match="r2-m1"]')
 await schedule.click()
 await dialog.locator('.schedule-filters > summary').click()
 await dialog.getByLabel('Player or team name',{exact:true}).fill('Casey')
 await dialog.getByLabel('Match court',{exact:true}).selectOption('2')
 await dialog.getByRole('button',{name:'Apply filters',exact:true}).click()
 await expect(match).toHaveCount(0)
 const requests=await requestCount(page)
 const overview=dialog.getByRole('button',{name:'Overview',exact:true})
 await overview.click();await jump.click()
 await expect(schedule).toHaveAttribute('aria-pressed','true')
 await expect(match.getByRole('heading')).toBeFocused()
 await expect(match.getByRole('heading')).toBeInViewport({ratio:1})
 await expect(match).toContainText('10:00 AM')
 await expect(match).toContainText('Court 1')
 expect(await requestCount(page)).toBe(requests)
 await bounded(page);await page.screenshot({path:info.outputPath('tournament-overview-schedule-jump.png')})
 const back=match.getByRole('button',{name:'Back to overview',exact:true})
 await back.click()
 await expect(jump).toBeFocused()
 await expect(jump).toBeInViewport({ratio:1})
 await schedule.click()
 await expect(dialog.getByLabel('Match court',{exact:true})).toHaveValue('2')
 await expect(match).toHaveCount(0)
 await overview.click();await jump.click()
 await dialog.getByRole('button',{name:'Draw',exact:true}).click()
 await expect(dialog.getByLabel('Player or team name',{exact:true})).toHaveValue('Casey')
 await expect(dialog.locator('.tournament-draw-match')).toHaveCount(1)
 await expect(dialog.locator('.tournament-draw-match')).toContainText('Casey Court')
 await schedule.click()
 await expect(dialog.getByLabel('Match court',{exact:true})).toHaveValue('2')
 await expect(match).toHaveCount(0)
 await overview.click();await jump.click()
 await page.clock.setFixedTime(new Date('2026-11-15T16:01:00Z'))
 await back.click()
 await expect(jump).toHaveCount(0)
 await expect(dialog.getByRole('heading',{name:'Round robin',exact:true})).toBeFocused()
 expect(await requestCount(page)).toBe(requests)
})
test('tournament cards show published signup deadlines for open events',async({page})=>{
 await page.setViewportSize({width:320,height:720})
 const dialog=await open(page,'registration-deadlines')
 await page.addStyleTag({content:':root{font-size:22px!important}'})
 const event=dialog.getByRole('article').filter({has:page.getByRole('heading',{name:'Northside Open',exact:true})})
 await expect(event.getByText('Registration open',{exact:true})).toBeVisible()
 await expect(event.locator('.tournament-card-deadline')).toHaveText('Enter by Thursday, November 12')
 await expect(event.locator('time')).toHaveAttribute('datetime','2026-11-12')
 await expect(dialog.locator('.competition-card time')).toHaveCount(1)
 await expect(dialog.getByText('Registration closed',{exact:true})).toBeVisible()
 await expect(dialog.getByText('Scheduled',{exact:true})).toBeVisible()
 await bounded(page)
 const opener=event.getByRole('button',{name:'Open tournament Northside Open',exact:true})
 await opener.click()
 await expect(dialog.getByRole('button',{name:'Open division 4.0 Doubles',exact:true})).toBeVisible()
 await expect(dialog.locator('.competition-card time')).toHaveCount(0)
 await dialog.getByRole('button',{name:'← Tournaments',exact:true}).click()
 await expect(opener).toBeFocused()
})
