test('tournament search lets players edit or broaden an empty result in place',async({page},info)=>{
 await page.setViewportSize({width:320,height:720})
 const dialog=await open(page)
 await page.addStyleTag({content:':root{font-size:22px!important}'})
 const search=dialog.getByRole('searchbox',{name:'Find a tournament',exact:true})
 await search.fill('nothing');await dialog.getByRole('button',{name:'Search',exact:true}).click()
 await expect(dialog.getByRole('heading',{name:'No tournaments found',exact:true})).toBeFocused()
 const title=dialog.getByRole('heading',{name:'Tournaments',exact:true})
 const titleFits=()=>title.evaluate(el=>el.getBoundingClientRect().height<=Number.parseFloat(getComputedStyle(el).lineHeight)+1)
 expect(await titleFits()).toBe(true)
 const largerText=await page.addStyleTag({content:':root{font-size:28px!important}'})
 expect(await titleFits()).toBe(true)
 await largerText.evaluate(el=>el.remove())
 await expect(dialog.getByRole('button',{name:'Clear search',exact:true})).toHaveCount(0)
 await dialog.getByRole('button',{name:'Edit search',exact:true}).click()
 await expect(search).toBeFocused();await expect(search).toHaveValue('nothing')
 expect(await search.evaluate(el=>[(el as HTMLInputElement).selectionStart,(el as HTMLInputElement).selectionEnd])).toEqual([0,7])
 await bounded(page);await page.screenshot({path:info.outputPath('tournament-search-empty.png')})
 await dialog.getByRole('button',{name:'Show all tournaments',exact:true}).click()
 await expect(dialog.getByText('1 tournament shown',{exact:true})).toBeFocused()
 await expect(search).toHaveValue('')
 await expect(dialog.getByRole('button',{name:'Open tournament Northside Open',exact:true})).toBeVisible()
})
test('offline refresh clears old draw and then recovers',async({page})=>{const d=await division(page);await change(page,{offline:true});await d.getByRole('button',{name:'Refresh tournaments',exact:true}).click();await expect(d.getByRole('alert')).toContainText('Couldn’t load');await expect(d).not.toContainText('Alex Ace');await change(page,{offline:false});await d.getByRole('button',{name:'Refresh tournaments',exact:true}).click();await expect(d.getByRole('button',{name:'Draw',exact:true})).toBeVisible()})
